import {
  index,
  pgEnum,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
} from "drizzle-orm/pg-core";

export const roleEnum = pgEnum("role", ["ADMIN", "EMPLOYEE"]);
export const postStatusEnum = pgEnum("post_status", ["DRAFT", "PUBLISHED", "ARCHIVED"]);
export const copyTypeEnum = pgEnum("copy_type", ["REPOST", "COMMENT"]);
export const mediaTypeEnum = pgEnum("media_type", ["NONE", "IMAGE", "CAROUSEL", "VIDEO", "DOCUMENT"]);

export const users = pgTable(
  "users",
  {
    id: text("id").primaryKey(),
    email: text("email").notNull(),
    name: text("name").notNull(),
    passwordHash: text("password_hash").notNull(),
    role: roleEnum("role").notNull().default("EMPLOYEE"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [uniqueIndex("users_email_unique").on(table.email)],
);

export const posts = pgTable("posts", {
  id: text("id").primaryKey(),
  caption: text("caption").notNull(),
  postUrl: text("post_url").notNull(),
  mediaType: mediaTypeEnum("media_type").notNull().default("NONE"),
  mediaJson: text("media_json").notNull().default("[]"),
  linksJson: text("links_json").notNull().default("[]"),
  contextLinksJson: text("context_links_json").notNull().default("[]"),
  contextBrief: text("context_brief"),
  status: postStatusEnum("status").notNull().default("DRAFT"),
  createdById: text("created_by_id").notNull().references(() => users.id),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

export const styleGuides = pgTable("style_guides", {
  id: text("id").primaryKey(),
  content: text("content").notNull(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  updatedById: text("updated_by_id").notNull().references(() => users.id),
});

export const amplifiedCopies = pgTable(
  "amplified_copies",
  {
    id: text("id").primaryKey(),
    postId: text("post_id").notNull().references(() => posts.id, { onDelete: "cascade" }),
    userId: text("user_id").notNull().references(() => users.id),
    type: copyTypeEnum("type").notNull(),
    content: text("content").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [index("amplified_copies_post_user_idx").on(table.postId, table.userId)],
);

export const roleWritingInstructions = pgTable("role_writing_instructions", {
  role: text("role").primaryKey(),
  content: text("content").notNull(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  updatedById: text("updated_by_id").notNull().references(() => users.id),
});

export type User = typeof users.$inferSelect;
export type Post = typeof posts.$inferSelect;
export type StyleGuide = typeof styleGuides.$inferSelect;
export type AmplifiedCopy = typeof amplifiedCopies.$inferSelect;
export type RoleWritingInstruction = typeof roleWritingInstructions.$inferSelect;