import { Router, type IRouter } from "express";
import crypto from "node:crypto";
import { desc, eq } from "drizzle-orm";
import {
  GetStyleGuideResponse,
  UpdateStyleGuideBody,
  UpdateStyleGuideResponse,
} from "@workspace/api-zod";
import { db, styleGuides } from "@workspace/db";
import { requireAdmin, requireUser } from "../lib/auth";

const router: IRouter = Router();

router.get("/style-guide", async (req, res) => {
  if (!requireUser(req, res)) return;
  const guide = await db.select().from(styleGuides).orderBy(desc(styleGuides.updatedAt)).limit(1);
  if (!guide[0]) {
    res.status(404).json({ error: "Style guide not found." });
    return;
  }
  res.json(GetStyleGuideResponse.parse(guide[0]));
});

router.put("/style-guide", async (req, res) => {
  const user = requireAdmin(req, res);
  if (!user) return;
  const parsed = UpdateStyleGuideBody.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: "Invalid request." });
    return;
  }
  const existing = await db.select().from(styleGuides).orderBy(desc(styleGuides.updatedAt)).limit(1);
  let updated;
  if (existing[0]) {
    updated = await db.update(styleGuides).set({
      content: parsed.data.content,
      updatedById: user.id,
      updatedAt: new Date(),
    }).where(eq(styleGuides.id, existing[0].id)).returning();
  } else {
    updated = await db.insert(styleGuides).values({
      id: crypto.randomUUID(),
      content: parsed.data.content,
      updatedById: user.id,
      updatedAt: new Date(),
    }).returning();
  }
  res.json(UpdateStyleGuideResponse.parse(updated[0]));
});

export default router;