import { Router, type IRouter } from "express";
import healthRouter from "./health";
import authRouter from "./auth";
import postsRouter from "./posts";
import styleGuideRouter from "./style-guide";
import generateCopyRouter from "./generate-copy";
import storageRouter from "./storage";
import roleInstructionsRouter from "./role-instructions";

const router: IRouter = Router();

router.use(healthRouter);
router.use(authRouter);
router.use(postsRouter);
router.use(styleGuideRouter);
router.use(roleInstructionsRouter);
router.use(generateCopyRouter);
router.use(storageRouter);

export default router;
