import crypto from "node:crypto";
import type { NextFunction, Request, Response } from "express";
import bcrypt from "bcryptjs";
import { eq } from "drizzle-orm";
import { db, users, type User } from "@workspace/db";

const COOKIE_NAME = "opus_session";
const MAX_AGE_SECONDS = 60 * 60 * 24 * 7;

export type SessionUser = Pick<User, "id" | "email" | "name" | "role">;

function secret(): string {
  const value = process.env.SESSION_SECRET;
  if (!value) throw new Error("SESSION_SECRET must be configured.");
  return value;
}

function encode(value: string): string {
  return Buffer.from(value, "utf8").toString("base64url");
}

function decode(value: string): string {
  return Buffer.from(value, "base64url").toString("utf8");
}

function sign(payload: string): string {
  return crypto.createHmac("sha256", secret()).update(payload).digest("base64url");
}

function tokenFor(user: SessionUser): string {
  const payload = encode(JSON.stringify({ ...user, exp: Math.floor(Date.now() / 1000) + MAX_AGE_SECONDS }));
  return `${payload}.${sign(payload)}`;
}

function userFromToken(token: string): SessionUser | null {
  const [payload, signature] = token.split(".");
  const expected = payload ? sign(payload) : "";
  if (!payload || !signature || signature.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected))) return null;
  try {
    const value = JSON.parse(decode(payload)) as SessionUser & { exp?: number };
    if (!value.exp || value.exp < Math.floor(Date.now() / 1000)) return null;
    if (!value.id || !value.email || !value.name || (value.role !== "ADMIN" && value.role !== "EMPLOYEE")) return null;
    return { id: value.id, email: value.email, name: value.name, role: value.role };
  } catch {
    return null;
  }
}

export async function authenticate(email: string, password: string): Promise<SessionUser | null> {
  const user = await db.select().from(users).where(eq(users.email, email)).limit(1);
  if (!user[0] || !(await bcrypt.compare(password, user[0].passwordHash))) return null;
  return { id: user[0].id, email: user[0].email, name: user[0].name, role: user[0].role };
}

export function setSession(res: Response, user: SessionUser): void {
  res.cookie(COOKIE_NAME, tokenFor(user), {
    httpOnly: true,
    signed: false,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    maxAge: MAX_AGE_SECONDS * 1000,
    path: "/",
  });
}

export function clearSession(res: Response): void {
  res.clearCookie(COOKIE_NAME, { httpOnly: true, sameSite: "lax", path: "/" });
}

export function sessionMiddleware(req: Request, _res: Response, next: NextFunction): void {
  const token = req.cookies?.[COOKIE_NAME];
  req.user = token ? userFromToken(token) : null;
  next();
}

export function requireUser(req: Request, res: Response): SessionUser | null {
  if (!req.user) {
    res.status(401).json({ error: "Not authenticated." });
    return null;
  }
  return req.user;
}

export function requireAdmin(req: Request, res: Response): SessionUser | null {
  const user = requireUser(req, res);
  if (!user) return null;
  if (user.role !== "ADMIN") {
    res.status(403).json({ error: "Administrator access required." });
    return null;
  }
  return user;
}

declare global {
  namespace Express {
    interface Request {
      user?: SessionUser | null;
    }
  }
}