import { Router, type IRouter } from "express";
import crypto from "node:crypto";
import { and, desc, eq } from "drizzle-orm";
import {
  CreatePostBody,
  CreatePostResponse,
  DeletePostParams,
  GetPostParams,
  GetPostResponse,
  ListPostsQueryParams,
  ListPostsResponse,
  UpdatePostBody,
  UpdatePostParams,
  UpdatePostResponse,
} from "@workspace/api-zod";
import { db, posts } from "@workspace/db";
import { requireAdmin, requireUser } from "../lib/auth";

const router: IRouter = Router();

function jsonArray(value: string): unknown[] {
  try {
    const result: unknown = JSON.parse(value);
    return Array.isArray(result) ? result : [];
  } catch {
    return [];
  }
}

function present(post: typeof posts.$inferSelect) {
  return {
    id: post.id,
    caption: post.caption,
    postUrl: post.postUrl,
    mediaType: post.mediaType,
    media: jsonArray(post.mediaJson),
    links: jsonArray(post.linksJson),
    contextLinks: jsonArray(post.contextLinksJson),
    status: post.status,
    createdAt: post.createdAt,
    updatedAt: post.updatedAt,
  };
}

router.get("/posts", async (req, res) => {
  const parsed = ListPostsQueryParams.safeParse(req.query);
  if (!parsed.success) {
    res.status(400).json({ error: "Invalid query." });
    return;
  }
  if (parsed.data.scope === "all" && !requireAdmin(req, res)) return;
  if (parsed.data.scope !== "all" && !requireUser(req, res)) return;
  const rows = parsed.data.scope === "all"
    ? await db.select().from(posts).orderBy(desc(posts.createdAt))
    : await db.select().from(posts).where(eq(posts.status, "PUBLISHED")).orderBy(desc(posts.createdAt));
  res.json(ListPostsResponse.parse(rows.map(present)));
});

router.post("/posts", async (req, res) => {
  const user = requireAdmin(req, res);
  if (!user) return;
  const parsed = CreatePostBody.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: "Invalid request.", details: parsed.error.flatten() });
    return;
  }
  const input = parsed.data;
  const now = new Date();
  const row = {
    id: crypto.randomUUID(),
    caption: input.caption,
    postUrl: input.postUrl,
    mediaType: input.mediaType,
    mediaJson: JSON.stringify(input.media),
    linksJson: JSON.stringify(input.links),
    contextLinksJson: JSON.stringify(input.contextLinks),
    status: input.status,
    createdById: user.id,
    createdAt: now,
    updatedAt: now,
  };
  const created = await db.insert(posts).values(row).returning();
  res.status(201).json(CreatePostResponse.parse(present(created[0])));
});

router.get("/posts/:id", async (req, res) => {
  const user = requireUser(req, res);
  if (!user) return;
  const params = GetPostParams.safeParse(req.params);
  if (!params.success) {
    res.status(400).json({ error: "Invalid post id." });
    return;
  }
  const row = await db.select().from(posts).where(
    user.role === "ADMIN"
      ? eq(posts.id, params.data.id)
      : and(eq(posts.id, params.data.id), eq(posts.status, "PUBLISHED")),
  ).limit(1);
  if (!row[0]) {
    res.status(404).json({ error: "Post not found." });
    return;
  }
  res.json(GetPostResponse.parse(present(row[0])));
});

router.patch("/posts/:id", async (req, res) => {
  const user = requireAdmin(req, res);
  if (!user) return;
  const params = UpdatePostParams.safeParse(req.params);
  const parsed = UpdatePostBody.safeParse(req.body);
  if (!params.success || !parsed.success) {
    res.status(400).json({ error: "Invalid request." });
    return;
  }
  const existing = await db.select().from(posts).where(eq(posts.id, params.data.id)).limit(1);
  if (!existing[0]) {
    res.status(404).json({ error: "Post not found." });
    return;
  }
  const input = parsed.data;
  const changedContext = JSON.stringify(input.contextLinks) !== existing[0].contextLinksJson;
  const updated = await db.update(posts).set({
    caption: input.caption,
    postUrl: input.postUrl,
    mediaType: input.mediaType,
    mediaJson: JSON.stringify(input.media),
    linksJson: JSON.stringify(input.links),
    contextLinksJson: JSON.stringify(input.contextLinks),
    contextBrief: changedContext ? null : existing[0].contextBrief,
    status: input.status,
    updatedAt: new Date(),
  }).where(eq(posts.id, params.data.id)).returning();
  res.json(UpdatePostResponse.parse(present(updated[0])));
});

router.delete("/posts/:id", async (req, res) => {
  if (!requireAdmin(req, res)) return;
  const params = DeletePostParams.safeParse(req.params);
  if (!params.success) {
    res.status(400).json({ error: "Invalid post id." });
    return;
  }
  const deleted = await db.delete(posts).where(eq(posts.id, params.data.id)).returning({ id: posts.id });
  if (!deleted[0]) {
    res.status(404).json({ error: "Post not found." });
    return;
  }
  res.status(204).end();
});

export default router;