import crypto from "node:crypto";
import dns from "node:dns/promises";
import net from "node:net";
import OpenAI from "openai";
import * as cheerio from "cheerio";
import { linkedinCaptionCtaGuidance, linkedinWritingPrinciples } from "./linkedin-writing";

let client: OpenAI | null = null;
function getClient(): OpenAI {
  if (!client) {
    const apiKey = process.env.AI_INTEGRATIONS_OPENAI_API_KEY ?? process.env.OPENAI_API_KEY;
    const baseURL = process.env.AI_INTEGRATIONS_OPENAI_BASE_URL;
    if (!apiKey) throw new Error("AI copy generation is not configured.");
    client = new OpenAI({ apiKey, baseURL });
  }
  return client;
}

async function fetchPageText(rawUrl: string): Promise<string | null> {
  let url: URL;
  try {
    url = new URL(rawUrl);
  } catch {
    return null;
  }
  const maxBytes = 1_000_000;
  const maxRedirects = 5;
  const visited = new Set<string>();

  for (let hop = 0; hop <= maxRedirects; hop += 1) {
    if (!["http:", "https:"].includes(url.protocol)) return null;
    if (visited.has(url.href)) return null;
    visited.add(url.href);
    if (!(await isSafeHostname(url.hostname))) return null;

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 8000);
    try {
      const response = await fetch(url, {
        signal: controller.signal,
        redirect: "manual",
        headers: { "User-Agent": "OpusAmplifyBot/1.0", Accept: "text/html,application/xhtml+xml" },
      });
      if (response.status >= 300 && response.status < 400) {
        const location = response.headers.get("location");
        if (!location || hop === maxRedirects) return null;
        try {
          url = new URL(location, url);
        } catch {
          return null;
        }
        continue;
      }
      if (!response.ok) return null;
      const contentType = (response.headers.get("content-type") ?? "").split(";", 1)[0].trim().toLowerCase();
      if (contentType !== "text/html" && contentType !== "application/xhtml+xml") return null;
      const declaredLength = Number(response.headers.get("content-length"));
      if (Number.isFinite(declaredLength) && declaredLength > maxBytes) return null;
      const body = await readResponseBody(response, maxBytes);
      if (body === null) return null;
      const $ = cheerio.load(body);
      $("script,style,nav,footer,noscript,svg,iframe").remove();
      return [$("title").first().text().trim(), $('meta[name="description"]').attr("content") ?? "", $("body").text().replace(/\s+/g, " ").trim()].filter(Boolean).join("\n\n").slice(0, 6000) || null;
    } catch {
      return null;
    } finally {
      clearTimeout(timeout);
    }
  }
  return null;
}

async function readResponseBody(response: Response, maxBytes: number): Promise<string | null> {
  if (!response.body) return "";
  const reader = response.body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      total += value.byteLength;
      if (total > maxBytes) {
        await reader.cancel();
        return null;
      }
      chunks.push(value);
    }
  } finally {
    reader.releaseLock();
  }
  const body = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    body.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return new TextDecoder().decode(body);
}

async function isSafeHostname(hostname: string): Promise<boolean> {
  const normalized = hostname.replace(/^\[|\]$/g, "").toLowerCase();
  if (normalized === "localhost" || net.isIP(normalized) && isReservedAddress(normalized)) return false;
  let addresses: Array<{ address: string; family: number }>;
  try {
    addresses = await dns.lookup(normalized, { all: true, verbatim: true });
  } catch {
    return false;
  }
  return addresses.length > 0 && addresses.every(({ address }) => !isReservedAddress(address));
}

function isReservedAddress(address: string): boolean {
  const family = net.isIP(address);
  if (family === 4) {
    const octets = address.split(".").map(Number);
    const [a, b, c] = octets;
    return a === 0 || a === 10 || a === 127 || a >= 224 || (a === 100 && b >= 64 && b <= 127)
      || (a === 169 && b === 254) || (a === 172 && b >= 16 && b <= 31)
      || (a === 192 && (b === 0 || b === 168)) || (a === 198 && (b === 18 || b === 19))
      || (a === 198 && b === 51 && c === 100) || (a === 203 && b === 0 && c === 113);
  }
  if (family !== 6) return true;
  const normalized = address.toLowerCase();
  if (normalized === "::" || normalized === "::1" || normalized.startsWith("ff")
    || normalized.startsWith("fc") || normalized.startsWith("fd")
    || /^(fe[89ab])/.test(normalized)
    || /^(100:|2001:0:|2001:2:|2001:10:|2001:20:|2001:db8:)/.test(normalized)) return true;
  if (normalized.startsWith("::ffff:")) {
    return isReservedAddress(normalized.slice("::ffff:".length));
  }
  if (normalized.startsWith("::")) return true;
  return false;
}

export async function researchLinks(links: string[]): Promise<string> {
  if (!links.length) return "";
  const pages = await Promise.all(links.map(async (link) => ({ link, text: await fetchPageText(link) })));
  const usable = pages.filter((page): page is { link: string; text: string } => Boolean(page.text));
  if (!usable.length) return "";
  const response = await getClient().responses.create({
    model: process.env.OPENAI_RESEARCH_MODEL ?? "gpt-5-nano",
    reasoning: { effort: "low" },
    instructions: "Extract only facts explicitly present in these source pages. Return at most eight concise bullets, or exactly NONE if there are no useful facts.",
    input: usable.map((page, i) => `Source ${i + 1} (${page.link}):\n"""\n${page.text}\n"""`).join("\n\n"),
    max_output_tokens: 1500,
  });
  const text = response.output_text?.trim() ?? "";
  return text === "NONE" ? "" : text;
}

export async function generateAmplifiedCopy(input: {
  writingInstructions: string;
  roleLabel: string;
  postCaption: string;
  postLinks: string[];
  contextBrief: string;
  type: "REPOST" | "COMMENT";
  recentExamples: string[];
}): Promise<string> {
  const instruction = [
    `Write LinkedIn copy for an Opus Technologies employee using the perspective of a ${input.roleLabel}. Follow the shared and role-specific writing instructions exactly.`,
    "Output only finished copy, with no labels, markdown, quotation marks, or word-count notes.",
    "Use short paragraphs for reposts. Stay strictly grounded in the source caption and researched facts.",
    "# LinkedIn writing principles",
    linkedinWritingPrinciples,
    "# Writing instructions",
    input.writingInstructions,
    ...(input.type === "REPOST" ? ["# Approved caption CTAs", linkedinCaptionCtaGuidance] : []),
  ].join("\n");
  const kind = input.type === "REPOST"
    ? "Write a REPOST caption, targeting about 80 words."
    : "Write a COMMENT, targeting about 45 words. Do not repeat the original post.";
  const inputText = [
    kind,
    `Original post caption:\n"""\n${input.postCaption}\n"""`,
    input.postLinks.length ? `Links included:\n${input.postLinks.join("\n")}` : "",
    input.contextBrief ? `Grounded facts:\n${input.contextBrief}` : "",
    input.recentExamples.length ? `Use different wording and structure from:\n${input.recentExamples.join("\n---\n")}` : "",
    `Variation seed: ${crypto.randomUUID()}`,
  ].filter(Boolean).join("\n\n");
  const response = await getClient().responses.create({
    model: process.env.OPENAI_COPY_MODEL ?? "gpt-5.4-mini",
    reasoning: { effort: "low" },
    instructions: instruction,
    input: inputText,
    max_output_tokens: 2000,
  });
  const text = response.output_text?.trim();
  if (!text) throw new Error("OpenAI did not return text content.");
  return text;
}