import { Router, type IRouter } from "express";
import crypto from "node:crypto";
import { and, desc, eq } from "drizzle-orm";
import { GenerateCopyBody, GenerateCopyResponse } from "@workspace/api-zod";
import { amplifiedCopies, db, posts, roleWritingInstructions, styleGuides } from "@workspace/db";
import { requireUser } from "../lib/auth";
import { generateAmplifiedCopy, researchLinks } from "../lib/openai";
import { roleInstructions, type CompanyRole } from "../lib/role-instructions";

const router: IRouter = Router();

function arrayFromJson(value: string): string[] {
  try {
    const parsed: unknown = JSON.parse(value);
    return Array.isArray(parsed) && parsed.every((item): item is string => typeof item === "string") ? parsed : [];
  } catch {
    return [];
  }
}

router.post("/generate-copy", async (req, res) => {
  const user = requireUser(req, res);
  if (!user) return;
  const parsed = GenerateCopyBody.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: "Invalid request." });
    return;
  }
  const input = parsed.data;
  const postRows = await db.select().from(posts).where(and(eq(posts.id, input.postId), eq(posts.status, "PUBLISHED"))).limit(1);
  if (!postRows[0]) {
    res.status(404).json({ error: "Post not found." });
    return;
  }
  try {
    const post = postRows[0];
    const guide = await db.select().from(styleGuides).orderBy(desc(styleGuides.updatedAt)).limit(1);
    const roleGuide = await db.select().from(roleWritingInstructions).where(eq(roleWritingInstructions.role, input.role)).limit(1);
    const recent = await db.select({ content: amplifiedCopies.content })
      .from(amplifiedCopies)
      .where(and(eq(amplifiedCopies.postId, input.postId), eq(amplifiedCopies.type, input.type)))
      .orderBy(desc(amplifiedCopies.createdAt))
      .limit(5);
    let contextBrief = post.contextBrief;
    if (contextBrief === null) {
      contextBrief = await researchLinks([...new Set([...arrayFromJson(post.contextLinksJson), ...arrayFromJson(post.linksJson)])]);
      await db.update(posts).set({ contextBrief, updatedAt: new Date() }).where(eq(posts.id, post.id));
    }
    const content = await generateAmplifiedCopy({
      writingInstructions: [
        guide[0]?.content ?? "",
        `Recommended role guidance:\n${roleInstructions[input.role as CompanyRole].content}`,
        roleGuide[0]?.content ? `Additional saved role instructions:\n${roleGuide[0].content}` : "",
      ].filter(Boolean).join("\n\n"),
      roleLabel: roleInstructions[input.role as CompanyRole].label,
      postCaption: post.caption,
      postLinks: arrayFromJson(post.linksJson),
      contextBrief,
      type: input.type,
      recentExamples: recent.map((item) => item.content),
    });
    const saved = await db.insert(amplifiedCopies).values({
      id: crypto.randomUUID(),
      postId: post.id,
      userId: user.id,
      type: input.type,
      content,
      createdAt: new Date(),
    }).returning();
    res.json(GenerateCopyResponse.parse({ id: saved[0].id, content: saved[0].content }));
  } catch (error) {
    req.log.error({ err: error, postId: input.postId }, "copy generation failed");
    const message = error instanceof Error && error.message.includes("not configured")
      ? "AI copy generation isn't configured yet. Contact an admin."
      : "Couldn't generate copy right now. Try again.";
    res.status(502).json({ error: message });
  }
});

export default router;