import { Router, type IRouter } from "express";
import crypto from "node:crypto";
import bcrypt from "bcryptjs";
import { count, sql } from "drizzle-orm";
import { db, users } from "@workspace/db";
import {
  BootstrapBody,
  BootstrapResponse,
  GetBootstrapStatusResponse,
  GetCurrentUserResponse,
  LoginBody,
  LoginResponse,
} from "@workspace/api-zod";
import { authenticate, clearSession, setSession } from "../lib/auth";

const router: IRouter = Router();

router.get("/auth/me", (req, res) => {
  res.json(GetCurrentUserResponse.parse({ user: req.user ?? null }));
});

router.get("/auth/bootstrap-status", async (_req, res) => {
  const [{ userCount }] = await db.select({ userCount: count() }).from(users);
  res.json(GetBootstrapStatusResponse.parse({ available: userCount === 0 }));
});

router.post("/auth/bootstrap", async (req, res) => {
  const parsed = BootstrapBody.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: "Invalid request.", details: parsed.error.flatten() });
    return;
  }

  const email = parsed.data.email.trim().toLowerCase();
  const name = parsed.data.name.trim();
  if (!name) {
    res.status(400).json({ error: "Name is required." });
    return;
  }
  const passwordHash = await bcrypt.hash(parsed.data.password, 12);

  try {
    const admin = await db.transaction(async (tx) => {
      // Serialize first-run setup so two simultaneous requests cannot both
      // observe an empty users table and create separate administrators.
      await tx.execute(sql`SELECT pg_advisory_xact_lock(74192831)`);
      const [{ userCount }] = await tx.select({ userCount: count() }).from(users);
      if (userCount !== 0) return null;
      return (await tx.insert(users).values({
        id: crypto.randomUUID(),
        email,
        name,
        passwordHash,
        role: "ADMIN",
      }).returning())[0];
    });

    if (!admin) {
      res.status(409).json({ error: "Initial administrator setup is no longer available." });
      return;
    }
    const sessionUser = { id: admin.id, email: admin.email, name: admin.name, role: admin.role };
    setSession(res, sessionUser);
    res.status(201).json(BootstrapResponse.parse(sessionUser));
  } catch (error) {
    req.log.error({ err: error }, "bootstrap setup failed");
    res.status(500).json({ error: "Unable to complete administrator setup." });
  }
});

router.post("/auth/login", async (req, res) => {
  const parsed = LoginBody.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: "Invalid request." });
    return;
  }
  try {
    const user = await authenticate(parsed.data.email, parsed.data.password);
    if (!user) {
      res.status(401).json({ error: "Invalid email or password." });
      return;
    }
    setSession(res, user);
    res.json(LoginResponse.parse(user));
  } catch (error) {
    req.log.error({ err: error }, "login failed");
    res.status(500).json({ error: "Authentication is not configured correctly." });
  }
});

router.post("/auth/logout", (_req, res) => {
  clearSession(res);
  res.status(204).end();
});

export default router;