import { Router, type IRouter } from "express";
import {
  ListRoleInstructionsResponse,
  UpdateRoleInstructionsBody,
  UpdateRoleInstructionsResponse,
} from "@workspace/api-zod";
import { db, roleWritingInstructions } from "@workspace/db";
import { requireAdmin, requireUser } from "../lib/auth";
import {
  companyRoleKeys,
  roleInstructions,
  type CompanyRole,
} from "../lib/role-instructions";

const router: IRouter = Router();

router.get("/role-instructions", async (req, res) => {
  if (!requireUser(req, res)) return;
  const saved = await db.select().from(roleWritingInstructions);
  const byRole = new Map(saved.map((item) => [item.role, item]));
  const result = companyRoleKeys.map((role) => {
    const item = byRole.get(role);
    return {
      role,
      label: roleInstructions[role].label,
      content: item?.content ?? roleInstructions[role].content,
      updatedAt: item?.updatedAt ?? new Date(0),
    };
  });
  res.json(ListRoleInstructionsResponse.parse(result));
});

router.put("/role-instructions", async (req, res) => {
  const user = requireAdmin(req, res);
  if (!user) return;
  const parsed = UpdateRoleInstructionsBody.safeParse(req.body);
  if (!parsed.success || !parsed.data.content.trim()) {
    res.status(400).json({ error: "Invalid request." });
    return;
  }
  const { role, content } = parsed.data;
  const updated = await db
    .insert(roleWritingInstructions)
    .values({
      role,
      content: content.trim(),
      updatedAt: new Date(),
      updatedById: user.id,
    })
    .onConflictDoUpdate({
      target: roleWritingInstructions.role,
      set: {
        content: content.trim(),
        updatedAt: new Date(),
        updatedById: user.id,
      },
    })
    .returning();
  res.json(
    UpdateRoleInstructionsResponse.parse({
      ...updated[0],
      label: roleInstructions[role as CompanyRole].label,
    }),
  );
});

export default router;
